import{_ as d}from"./_plugin-vue_export-helper-DlAUqK2U.js";import{o as v,c as b,d as i}from"./index-CQ4DV5PW.js";const s={},t={class:"privacy-page"};function c(e,a){return v(),b("div",t,a[0]||(a[0]=[i('<div class="page-header" data-v-b7861fb4><h1 class="page-title" data-v-b7861fb4>数据安全说明</h1></div><div class="privacy-card" data-v-b7861fb4><div class="section" data-v-b7861fb4><div class="section-icon" data-v-b7861fb4>🗄️</div><div class="section-body" data-v-b7861fb4><h3 data-v-b7861fb4>数据存储在你自己的服务器上</h3><p data-v-b7861fb4>本系统部署在你自有的云服务器中，客户数据（姓名、电话、身份证号、案件材料）全部存储在你控制的数据库里。运营方无法远程访问你的服务器或数据库。</p></div></div><div class="section" data-v-b7861fb4><div class="section-icon" data-v-b7861fb4>🔒</div><div class="section-body" data-v-b7861fb4><h3 data-v-b7861fb4>数据隔离</h3><p data-v-b7861fb4>每个账号只能查看自己创建的客户、案件和文书。不同律师所之间的数据完全隔离，同一律所内的多名律师也需要分别登录。</p></div></div><div class="section" data-v-b7861fb4><div class="section-icon" data-v-b7861fb4>🤖</div><div class="section-body" data-v-b7861fb4><h3 data-v-b7861fb4>AI 文书生成仅发送案情文本</h3><p data-v-b7861fb4>当你使用文书生成功能时，只有案由、事实描述、诉讼请求等文本会发送给 AI。当事人的姓名、电话、身份证号、微信等个人信息<b data-v-b7861fb4>不会</b>发送给第三方。</p></div></div><div class="section" data-v-b7861fb4><div class="section-icon" data-v-b7861fb4>🧑‍⚖️</div><div class="section-body" data-v-b7861fb4><h3 data-v-b7861fb4>符合律师执业规范</h3><p data-v-b7861fb4>系统设计时考虑了律师保密义务要求。你可以选择是否关闭 AI 功能，关闭后系统仍可正常用于案件管理、客户管理和文书编辑。</p></div></div><div class="section" data-v-b7861fb4><div class="section-icon" data-v-b7861fb4>📋</div><div class="section-body" data-v-b7861fb4><h3 data-v-b7861fb4>第三方服务</h3><p data-v-b7861fb4>文书生成功能依赖 DeepSeek API。DeepSeek 承诺不会使用用户数据训练模型，传输使用 HTTPS 加密。</p></div></div></div>',2)]))}const n=d(s,[["render",c],["__scopeId","data-v-b7861fb4"]]);export{n as default};
